//go:build linux
// +build linux

// Code generated by gen-cudss from cudss.h and the cuDSS 0.8.0 parameter
// reference. DO NOT EDIT.

package cudss

import (
	"testing"
	"unsafe"
)

// The sizes below were measured by clang from the pinned cuDSS 0.8.0 headers
// at generation time, and the primitive sizes they reduce to were asserted for
// linux/amd64 and linux/arm64 without running. This test is the Go half: it
// fails if a Go type an accessor uses stops matching the C type the parameter
// is documented to have, which is the failure that would otherwise show up as
// libcudss writing past a caller's variable.
//
// It needs no GPU and no libcudss.
func TestParamTypeSizes(t *testing.T) {
	for _, tc := range []struct {
		goType string
		cType  string
		got    uintptr
		want   uintptr
	}{
		{"FactorizationAlg", "cudssFactorizationAlg_t", unsafe.Sizeof(FactorizationAlg(0)), 4},
		{"MatchingAlg", "cudssMatchingAlg_t", unsafe.Sizeof(MatchingAlg(0)), 4},
		{"Matrix", "cudssMatrix_t", unsafe.Sizeof(Matrix(0)), 8},
		{"PivotEpsilonAlg", "cudssPivotEpsilonAlg_t", unsafe.Sizeof(PivotEpsilonAlg(0)), 4},
		{"PivotType", "cudssPivotType_t", unsafe.Sizeof(PivotType(0)), 4},
		{"ReorderingAlg", "cudssReorderingAlg_t", unsafe.Sizeof(ReorderingAlg(0)), 4},
		{"SolveAlg", "cudssSolveAlg_t", unsafe.Sizeof(SolveAlg(0)), 4},
		{"float64", "double", unsafe.Sizeof(float64(0)), 8},
		{"int32", "int", unsafe.Sizeof(int32(0)), 4},
		{"int64", "int64_t", unsafe.Sizeof(int64(0)), 8},
	} {
		if tc.got != tc.want {
			t.Errorf("Go %s is %d bytes, C %s is %d", tc.goType, tc.got, tc.cType, tc.want)
		}
	}
}

// TestParamTypeTables checks the tables against the counts gen-cudss recorded
// when it read the pinned header. gen-cudss fails if a tag the header declares
// has neither an accessor nor a stated reason for omitting one, so these
// numbers are the header's, not a wish: a table edited by hand after
// generation, or a regeneration against a header with different tags, shows up
// here instead of at a caller.
func TestParamTypeTables(t *testing.T) {
	if got, want := len(configParamTypes), 26; got != want {
		t.Errorf("configParamTypes has %d entries, generated from %d declared tags", got, want)
	}
	if got, want := len(dataParamTypes), 25; got != want {
		t.Errorf("dataParamTypes has %d entries, generated from %d declared tags", got, want)
	}
	for p, ct := range configParamTypes {
		if ct == "" {
			t.Errorf("%v has an accessor but no documented C type", p)
		}
	}
	for p, ct := range dataParamTypes {
		if ct == "" {
			t.Errorf("%v has an accessor but no documented C type", p)
		}
	}
	if got := ConfigParam(1 << 20).ParamType(); got != "" {
		t.Errorf("ParamType of an undeclared config tag = %q, want empty", got)
	}
	if got := DataParam(1 << 20).ParamType(); got != "" {
		t.Errorf("ParamType of an undeclared data tag = %q, want empty", got)
	}
}
